#!/usr/bin/env python3
from promote_l271_l300_common import make_lesson, run_batch
GX="src.web.gx-data-quality-use-cases"; GE="src.web.gx-expectations"; GXL="1_Nguon/Web/SRC-GX-DATA-QUALITY-USE-CASES"; GEL="1_Nguon/Web/SRC-GX-EXPECTATIONS"
def a(*items): return tuple((x.split("|",1)[0],x.split("|",1)[1]) for x in items)
S=(GX,GE); L=(GXL,GEL)
LESSONS=(
make_lesson(276,"Lesson_276-rule-anatomy-seven-parts","Rule anatomy - seven parts","wiki.data-quality.rule-anatomy","Một data-quality rule cần đủ bảy phần nào để có thể chạy, giải thích, vận hành và thay đổi an toàn?",S,L,a(
"Asset and population|Rule phải chỉ đúng asset, partition, filter và exclusions; tên bảng đơn lẻ không định nghĩa population.","Grain and subject|Đơn vị đánh giá có thể là row, key, group, interval hoặc whole asset; trộn grain làm denominator vô nghĩa.","Predicate and metric|Logic phải nêu phép đo, typed comparison, null semantics và cách xử lý lỗi thực thi.","Threshold and severity|Threshold có unit, inclusive boundary, warning/fail class và lý do kinh doanh; số đẹp không phải policy.","Owner and action|Failure cần owner, routing, containment, remediation và deadline; rule không có hành động chỉ tạo noise.","Version and evidence|Lưu rule version, parameters, input snapshot, observed value, failing samples và exception state.")),
make_lesson(277,"Lesson_277-layered-controls-where-each-check-belongs","Layered controls - where each check belongs","wiki.data-quality.layered-controls","Đặt check ở source, ingestion, transform, publish hay consumer boundary theo failure economics thế nào?",S,L,a(
"Source contract|Chặn schema/identity sai sớm khi source owner có thể sửa, nhưng không giả định source validation bảo vệ downstream semantics.","Ingestion boundary|Kiểm parse, envelope, completeness manifest, duplicates và quarantine trước khi raw evidence bị biến đổi.","Transformation layer|Kiểm business invariants gần logic tạo chúng, dùng intermediate assertions để thu hẹp blast radius.","Publication gate|Candidate chỉ được promote khi critical controls, reconciliation và freshness đạt; warning không âm thầm thành pass.","Consumer monitor|Kiểm use-case-visible totals, latency và availability vì upstream green vẫn có thể không phục vụ được decision.","Defense without duplication|Lặp check khi failure cost biện minh; mỗi lớp có purpose và owner khác nhau, tránh copy cùng SQL vô chủ.")),
make_lesson(278,"Lesson_278-schema-and-contract-tests-at-the-boundary","Schema and contract tests at the boundary","wiki.data-quality.schema-contract-boundary","Schema test và semantic contract test khác nhau thế nào tại producer-consumer boundary?",S,L,a(
"Structural schema|Columns, nested fields, types, nullability và order chỉ là cấu trúc; parse được chưa chứng minh meaning đúng.","Semantic contract|Grain, key, units, timezone, enum meaning, update/deletion policy và compatibility tạo consumer contract.","Compatibility direction|Backward và forward compatibility phụ thuộc ai đọc phiên bản nào; additive field không luôn an toàn với strict consumers.","Boundary fixtures|Giữ golden valid payload, missing/extra field, widened/narrowed type, null transition và changed-meaning case.","Enforcement modes|Observe, warn, quarantine và block cần rollout policy; block đột ngột có thể gây outage lớn hơn defect.","Contract evidence|Consumer inventory, schema diff, compatibility decision, owner approval và migration window phải cùng version.")),
make_lesson(279,"Lesson_279-row-aggregate-and-relationship-tests","Row, aggregate and relationship tests","wiki.data-quality.row-aggregate-relationship-tests","Chọn row, aggregate và relationship tests ra sao để không bỏ lọt lỗi bù trừ hoặc tạo scan thừa?",S,L,a(
"Row predicates|Row test định vị record vi phạm tốt nhưng cần null semantics, conditional population và stable failure identity.","Aggregate controls|Count, sum, distribution và ratio thấy drift toàn cục nhưng missing và duplicate có thể bù nhau.","Relationship checks|Referential, temporal và many-to-many constraints cần key normalization, effective-time alignment và orphan policy.","Cross-level triangulation|Kết hợp row samples, group totals và key-set anti-join để một lớp bù điểm mù của lớp kia.","Execution economics|Incremental partitions, sampled warning và full release check có coverage khác nhau phải được công bố.","Failure outputs|Result giữ failed keys, group dimensions, expected/observed metrics và query version để remediation khả thi.")),
make_lesson(280,"Lesson_280-temporal-tests-late-out-of-order-and-overlap","Temporal tests - late, out of order and overlap","wiki.data-quality.temporal-tests","Temporal tests phải mô hình late, out-of-order, overlap và correction bằng những clock và interval nào?",S,L,a(
"Multiple clocks|Event, source commit, ingestion, processing và publish time trả lời câu hỏi khác nhau; lag cần chỉ rõ cặp clock.","Watermark and lateness|Watermark là completeness claim có policy; allowed lateness quyết định sửa state hay route exception.","Out-of-order behavior|Arrival order không được giả làm business order; sequence/version tie-break phải deterministic và có collision path.","Interval overlap|Adjacent partitions dùng half-open boundary; correction window và replay overlap cần dedup identity.","Temporal invariants|Test no gap, no unintended overlap, monotonic transition và bounded outstanding lateness trên đúng grain.","DST and calendar|Local business days có thể 23/25 giờ; fixtures phải giữ timezone rules, ambiguous fold và manual trigger.")),
)
QUERIES={n:[f"L{n} rule boundary là gì?",f"L{n} test failure case nào?",f"L{n} evidence nào cần lưu?"] for n in range(276,281)}
VERIFY={n:"Tạo positive/negative fixture ở đúng grain, chạy rule đã version hóa và so failing keys/metrics với một oracle độc lập." for n in range(276,281)}
TAKEAWAYS={276:"Rule vận hành được cần population, grain, logic, threshold, severity, owner/action và versioned evidence.",277:"Check thuộc lớp có thể phát hiện và xử lý failure với chi phí thấp nhất.",278:"Schema là cấu trúc; contract còn sở hữu semantics và compatibility.",279:"Row, aggregate và relationship tests cần triangulate vì mỗi lớp có điểm mù.",280:"Temporal correctness bắt đầu bằng nhiều clock, half-open intervals và late policy."}
SOURCES=((GE,"1_Nguon/Web/SRC-GX-EXPECTATIONS.md","https://docs.greatexpectations.io/docs/core/define_expectations/","Great Expectations - Define Expectations","Expectations as verifiable assertions, suites, parameters, severity and validation workflow."),)
if __name__=="__main__": raise SystemExit(run_batch(lessons=LESSONS,queries=QUERIES,verification=VERIFY,takeaways=TAKEAWAYS,sources=SOURCES,version="1.0.55",timestamp="2026-10-02T23:59:55+07:00"))
